// x: 8-D 'ambient' adapter input (residuals.py's feature order for this
// adapter). Returns the 9-D world-frame residual d_k prediction
// (residuals.py::compute_targets' d_0..d_8 order: pos x/y/z, vel x/y/z, attitude x/y/z).
inline Eigen::VectorXd ambientForward(const Eigen::VectorXd &x)
{
  Eigen::VectorXd xn = (x - kAmbientInputMean).cwiseQuotient(kAmbientInputStd);
  Eigen::VectorXd h0 = (kAmbientW0 * xn + kAmbientB0).array().tanh();
  Eigen::VectorXd h1 = (kAmbientW1 * h0 + kAmbientB1).array().tanh();
  Eigen::VectorXd yn = kAmbientW2 * h1 + kAmbientB2;
  return yn.cwiseProduct(kAmbientOutputStd) + kAmbientOutputMean;
}

